return {
	-- Guide
	["A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra."] = "Un sombrero de tela al final de tus veintes: el encargo de Zardeth para cualquier jugador de la Alianza le da esto extra a los brujos.",

	-- Step 1: Zardeth of the Black Claw
	-- {npc:1435} Zardeth of the Black Claw · {object:2164} Slaughtered Lamb · {object:2101} Mage Quarter · {zone:1431} Duskwood · {zone:1437} Wetlands
	["At 25 {npc:1435}, in the cellar of the {object:2164} in the {object:2101} (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to {zone:1431} and the {zone:1437}."] = "A nivel 25, {npc:1435}, en el sótano de {object:2164} en {object:2101} (junto a los instructores de brujos), quiere dos ingredientes para un brebaje. Hazlo cuando tu leveleo te lleve a {zone:1431} y {zone:1437}.",

	-- Step 2: Tear of Tilloa
	-- {area:1098} Manor Mistmantle · {zone:1431} Duskwood · {area:42} Darkshire · {object:321} Tear of Tilloa · {npc:315} Stalvan Mistmantle
	-- plural, as words: Fetid Corpses = {npc:1270} Fetid Corpse
	["{area:1098} stands in the north-east of {zone:1431}, north of {area:42}. The {object:321} is a small white flower low in the grass of the fenced garden beside Stalvan's house: hard to see, so sweep the garden with your mouse. Fetid Corpses (level 29) wander the grounds and come quickly: at 25, send your voidwalker at the nearest one, grab the flower and leave. {npc:315} (32) is inside the house; leave him alone."] = "{area:1098} está en el noreste de {zone:1431}, al norte de {area:42}. {object:321} es una florecita blanca, baja en la hierba del jardín cercado junto a la casa de Stalvan: cuesta verla, así que recorre el jardín con el mouse. Los cadáveres fétidos (nivel 29) deambulan por el terreno y llegan rápido: a nivel 25, manda a tu abisario contra el más cercano, agarra la flor y vete. {npc:315} (32) está dentro de la casa; déjalo en paz.",

	-- Step 3: Musquash Root
	-- {area:836} Dun Algaz · {object:147516} Dark Iron (no name in this language: may be words) · {area:146} Stonewrought Dam
	["The root grows at the water's edge in the pool below the small falls east of {area:836}, beside the {object:147516} cave below the {area:146}: a tall, spiky wooden root, not at the foot of the dam itself."] = "La raíz crece en la orilla de la poza debajo de la pequeña cascada al este de {area:836}, junto a la cueva de {object:147516} debajo de {area:146}: una raíz de madera alta y espinosa, no al pie de la presa.",

	-- Step 4: A Noble Brew
	-- {item:2788} Black Claw Stout · {npc:1439} Lord Baurles K. Wishock · {object:2117} Stormwind Keep
	["Back to Zardeth. He brews the {item:2788} and gives it to you for {npc:1439} in the Hall of Petitioners, the first hall on the right inside {object:2117}."] = "De vuelta con Zardeth. Prepara {item:2788} y te la da para {npc:1439}, en la Sala de los Peticionarios, la primera sala a la derecha dentro de {object:2117}.",

	-- Step 5: You Have Served Us Well
	-- {npc:1733} Zggi
	["Back to Zardeth once more: he offers warlocks a reward, which his imp {npc:1733}, standing beside him, hands over."] = "De vuelta con Zardeth una vez más: les ofrece una recompensa a los brujos, que te entrega su diablillo {npc:1733}, que está a su lado.",
}
